--
-- Name: visual_feedback; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.visual_feedback (
    feedback_id bigint NOT NULL,
    user_id bigint,
    image_url text NOT NULL,
    image_hash character varying(64),
    predicted_trek_id integer,
    suggested_trek_id integer,
    feedback_type character varying(50) NOT NULL,
    user_notes text,
    verification_status character varying(30) DEFAULT 'pending'::character varying NOT NULL,
    reviewed_by bigint,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT visual_feedback_feedback_type_check CHECK (((feedback_type)::text = ANY ((ARRAY['correct_destination'::character varying, 'incorrect_destination'::character varying, 'wrong_landmark'::character varying, 'similar_different_trek'::character varying, 'not_sure'::character varying, 'inappropriate_image'::character varying])::text[]))),
    CONSTRAINT visual_feedback_verification_status_check CHECK (((verification_status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'disputed'::character varying])::text[])))
);


ALTER TABLE public.visual_feedback OWNER TO postgres;

--
-- Name: visual_feedback_feedback_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.visual_feedback_feedback_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.visual_feedback_feedback_id_seq OWNER TO postgres;

--
-- Name: visual_feedback_feedback_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.visual_feedback_feedback_id_seq OWNED BY public.visual_feedback.feedback_id;


--
-- Name: visual_processing_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.visual_processing_jobs (
    job_id bigint NOT NULL,
    post_id bigint,
    image_url text,
    job_type character varying(50) DEFAULT 'post_ingestion'::character varying NOT NULL,
    status character varying(30) DEFAULT 'pending'::character varying NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    error_message text,
    metadata jsonb DEFAULT '{}'::jsonb,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT visual_processing_jobs_job_type_check CHECK (((job_type)::text = ANY ((ARRAY['post_ingestion'::character varying, 'image_reembed'::character varying, 'backfill_batch'::character varying, 'knowledge_rebuild'::character varying])::text[]))),
    CONSTRAINT visual_processing_jobs_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'skipped'::character varying, 'retrying'::character varying])::text[])))
);


ALTER TABLE public.visual_processing_jobs OWNER TO postgres;

